<?php

namespace Phiki\Grammar;

use Phiki\Contracts\GrammarRepositoryInterface;

// This file is automatically generated and should not be edited manually.
enum Grammar: string
{
    case Txt = 'txt';
    case Antlers = 'antlers';
    {cases}

    public function aliases(): array
    {
        return match ($this) {
            {aliases}
            self::Antlers => [],
            self::Txt => ['plaintext', 'text', 'plain'],
        };
    }

    public function scopeName(): string
    {
        return match ($this) {
            {scopeNames}
            self::Antlers => 'text.html.statamic',
            self::Txt => 'text.plain'
        };
    }

    /**
     * Get the path to the grammar file written for the given regex engine.
     */
    public function path(string $engine = 'oniguruma'): string
    {
        return __DIR__ . "/../../resources/grammars/{$engine}/{$this->value}.json";
    }

    public static function parse(array $grammar): ParsedGrammar
    {
        return (new GrammarParser)->parse($grammar);
    }

    public function toParsedGrammar(GrammarRepositoryInterface $repository): ParsedGrammar
    {
        return $repository->get($this->value);
    }
}
